import pandas as pdimport json# --- Configuration ---INPUT_SUMMARY_FILE = "behavior_summary.csv"OUTPUT_LAYER_FILE = "attck_navigator_layer_fixed.json"  # Using a new name for claritydef create_navigator_layer(input_file, output_file):    """    Reads the summary CSV and creates the MITRE ATT&CK Navigator JSON layer file.    """    try:        summary_df = pd.read_csv(input_file)    except FileNotFoundError:        print(f"Error: Input file '{input_file}' not found.")        return    navigator_layer = {        "name": "Combined Malware Analysis (by Frequency)",        "description": "ATT&CK techniques observed across analyzed samples. Score = Total Count.",        # --- FIX APPLIED HERE ---        "versions": {"attack": "14", "navigator": "4.9.1"},  # Setting explicit versions        "domain": "enterprise-attack",        "techniques": []    }    # Iterate through the summary data to create technique entries    for index, row in summary_df.iterrows():        technique_id = row['ATTACK_ID']        total_count = int(row['Total_Count'])        families = row['Families']        # Determine color/score.        if total_count >= 10:            color = "#ff6666"        elif total_count >= 5:            color = "#ffcc66"        else:            color = "#ffff66"        navigator_layer['techniques'].append({            "techniqueID": technique_id,            "comment": f"Count: {total_count}. Observed in families: {families}",            "score": total_count        })    # Save the JSON layer file    with open(output_file, 'w') as f:        json.dump(navigator_layer, f, indent=4)    print(f"\n✅ FIXED ATT&CK Navigator Layer File successfully created: {output_file}")if __name__ == "__main__":    create_navigator_layer(INPUT_SUMMARY_FILE, OUTPUT_LAYER_FILE)